// ================================================

const MODE = 'check'; // 'check' или 'book', не менять

const WEEKDAYS = ['понеділок', 'вівторок', 'середа', 'четвер', "п'ятниця", 'субота', 'неділя'];
const MONTHS = ['січня', 'лютого', 'березня', 'квітня', 'травня', 'червня', 'липня', 'серпня', 'вересня', 'жовтня', 'листопада', 'грудня'];

const raw = $input.first().json;
const b = { ...(raw.query || {}), ...(raw.body || {}) };
const zone = CONFIG.timezone;
const now = DateTime.now().setZone(zone);

const fail = (message, extra = {}) => [{
  json: { ok: false, ...(MODE === 'book' ? { booked: false } : { available: false }), message, ...extra },
}];

function parseDate(v) {
  const s = String(v ?? '').trim().toLowerCase();
  if (['сьогодні', 'сегодня', 'today'].includes(s)) return now.startOf('day');
  if (['завтра', 'tomorrow'].includes(s)) return now.plus({ days: 1 }).startOf('day');
  if (['післязавтра', 'послезавтра'].includes(s)) return now.plus({ days: 2 }).startOf('day');
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return DateTime.fromObject({ year: +m[1], month: +m[2], day: +m[3] }, { zone });
  m = s.match(/^(\d{1,2})[.\/](\d{1,2})(?:[.\/](\d{2,4}))?$/);
  if (m) {
    let year = m[3] ? +m[3] : now.year;
    if (year < 100) year += 2000;
    let d = DateTime.fromObject({ year, month: +m[2], day: +m[1] }, { zone });
    if (!m[3] && d.isValid && d < now.startOf('day')) d = d.plus({ years: 1 });
    return d;
  }
  return null;
}

function parseTime(v) {
  const m = String(v ?? '').trim().match(/^(\d{1,2})(?:[:.](\d{2}))?$/);
  if (!m) return null;
  const hour = +m[1];
  const minute = +(m[2] || 0);
  if (hour > 23 || minute > 59) return null;
  return { hour, minute };
}

const day = parseDate(b.date);
if (!day || !day.isValid) {
  return fail('Не вдалося розпізнати дату. Уточніть дату й передайте її у форматі YYYY-MM-DD.');
}
const t = parseTime(b.time);
if (!t) {
  return fail('Не вдалося розпізнати час. Уточніть час і передайте його у форматі HH:mm.');
}

let guests = null;
if (b.guests !== undefined && b.guests !== null && String(b.guests).trim() !== '') {
  guests = parseInt(b.guests, 10);
  if (isNaN(guests) || guests < 1) return fail('Уточніть кількість гостей.');
}
if (guests && CONFIG.maxGuestsPerTable && guests > CONFIG.maxGuestsPerTable) {
  return fail(
    `Онлайн-бронь доступна для компаній до ${CONFIG.maxGuestsPerTable} гостей. Для більшої компанії запропонуйте передати контакт адміністратору.`,
    { needs_admin: true },
  );
}

const start = day.set({ hour: t.hour, minute: t.minute, second: 0, millisecond: 0 });
const end = start.plus({ minutes: CONFIG.durationMinutes });
const [oh, om] = CONFIG.openTime.split(':').map(Number);
const [ch, cm] = CONFIG.closeTime.split(':').map(Number);
const open = day.set({ hour: oh, minute: om, second: 0, millisecond: 0 });
let close = day.set({ hour: ch, minute: cm, second: 0, millisecond: 0 });
if (close <= open) close = close.plus({ days: 1 });

if (start < now.plus({ minutes: CONFIG.minLeadMinutes })) {
  return fail(`Цей час уже минув або до нього менше ${CONFIG.minLeadMinutes} хвилин. Запропонуйте інший час.`);
}
if (start < open || end > close) {
  return fail(
    `Бронь можлива з ${CONFIG.openTime}, і вона має закінчитися до ${CONFIG.closeTime}. Одна бронь триває ${CONFIG.durationMinutes / 60} год. Запропонуйте інший час.`,
  );
}

let name = null;
let phone = null;
let comment = null;
if (MODE === 'book') {
  name = String(b.name ?? '').trim();
  phone = String(b.phone ?? '').trim();
  comment = String(b.comment ?? '').trim() || null;
  if (!name) return fail("Потрібне ім'я гостя. Запитайте ім'я і повторіть бронювання.");
  if (phone.replace(/\D/g, '').length < 9) {
    return fail('Потрібен номер телефону гостя. Запитайте номер і повторіть бронювання.');
  }
}

const dateText = `${WEEKDAYS[start.weekday - 1]}, ${start.day} ${MONTHS[start.month - 1]}`;

return [{
  json: {
    ok: true,
    date: start.toFormat('yyyy-MM-dd'),
    time: start.toFormat('HH:mm'),
    end_time: end.toFormat('HH:mm'),
    date_text: dateText,
    start: start.toISO(),
    end: end.toISO(),
    open: open.toISO(),
    close: close.toISO(),
    guests,
    name,
    phone,
    comment,
    table_id: b.table_id ? String(b.table_id).trim() : null,
    config: CONFIG,
  },
}];

// Один элемент на каждый столик: нода Google Calendar смотрит занятость каждого
// на весь рабочий день, чтобы при занятом времени сразу предложить ближайшее свободное.
const req = $input.first().json;
return req.config.tables.map((t) => ({
  json: {
    id: t.id,
    name: t.name,
    calendarId: t.calendarId,
    timeMin: req.open,
    timeMax: req.close,
  },
}));

// Считаем, свободен ли хоть один столик на запрошенное время.
// Если нет — ищем до 3 ближайших свободных вариантов в тот же день.
const req = $('Разбор запроса').first().json;
const cfg = req.config;
const zone = cfg.timezone;
const tables = $('Столики на день').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);
const toMs = (iso) => DateTime.fromISO(iso).toMillis();

const errs = {};
const checked = tables.map((t, i) => {
  const r = results[i] || {};
  if (r.error || !r.calendars) {
    const k = String(r.error ? (typeof r.error === 'string' ? r.error : JSON.stringify(r.error)) : 'пустой ответ Google').slice(0, 200);
    errs[k] = (errs[k] || 0) + 1;
    return { ...t, ok: false, busy: [] };
  }
  const cal = r.calendars[t.calendarId] || Object.values(r.calendars)[0] || {};
  return { ...t, ok: true, busy: (cal.busy || []).map((x) => [toMs(x.start), toMs(x.end)]) };
});
const usable = checked.filter((t) => t.ok);
const broken = checked.filter((t) => !t.ok).map((t) => t.name);
const diagnose = () => Object.entries(errs).map(([e, c]) => `${e} (${c} календ.)`).join('; ');

if (!usable.length) {
  return [{
    json: {
      ok: false,
      available: false,
      technical_error: true,
      message: 'Технічна помилка: не вдалося перевірити календар. Вибачтеся й запропонуйте передати контакт адміністратору.',
      debug_for_admin: diagnose(),
    },
  }];
}

const isFree = (t, s, e) => !t.busy.some(([bs, be]) => s < be && e > bs);
const s = toMs(req.start);
const e = toMs(req.end);
const free = usable.filter((t) => isFree(t, s, e));

const base = {
  ok: true,
  date: req.date,
  date_text: req.date_text,
  time: req.time,
  end_time: req.end_time,
  ...(broken.length ? { unchecked_tables: broken, debug_for_admin: diagnose() } : {}),
};

if (free.length) {
  return [{
    json: {
      ...base,
      available: true,
      table_id: free[0].id,
      table_name: free[0].name,
      free_tables: free.length,
      message: `Є вільний столик: ${req.date_text}, ${req.time}–${req.end_time}. Можна бронювати.`,
    },
  }];
}

const dur = cfg.durationMinutes * 60000;
const step = cfg.slotStepMinutes * 60000;
const earliest = DateTime.now().plus({ minutes: cfg.minLeadMinutes }).toMillis();
const open = toMs(req.open);
const close = toMs(req.close);
const options = [];
for (let t0 = open; t0 + dur <= close; t0 += step) {
  if (t0 === s || t0 < earliest) continue;
  if (usable.some((t) => isFree(t, t0, t0 + dur))) options.push(t0);
}
const alternatives = options
  .sort((a, b) => Math.abs(a - s) - Math.abs(b - s))
  .slice(0, 3)
  .sort((a, b) => a - b)
  .map((ms) => DateTime.fromMillis(ms, { zone }).toFormat('HH:mm'));

return [{
  json: {
    ...base,
    available: false,
    alternatives,
    message: alternatives.length
      ? `На ${req.time} усі столики зайняті. Вільний час цього дня: ${alternatives.join(', ')}. Запропонуйте гостю один із варіантів.`
      : `На цей день (${req.date_text}) вільних столиків немає. Запропонуйте гостю інший день.`,
  },
}];
